use strict; use warnings;

my %UNCOUNTABLE = map {$_=>1} qw(equipment information rice money species series fish sheep jeans police);

sub pluralize { my $w=shift; return $UNCOUNTABLE{$w} ? $w : $w."s"; }

sub singularize {
    my $w = shift;
    return $w if $UNCOUNTABLE{$w};
    if ($w =~ /((a)naly|(b)a|(d)iagno|(p)arenthe|(p)rogno|(s)ynop|(t)he)ses$/) { my $r=$1.($2//'').'sis'; return substr($w,0,$-[0]).$r; }
    if ($w =~ /([^aeiouy]|qu)ies$/) { return substr($w,0,$-[0]).$1.'y'; }
    if ($w =~ /([^f])ves$/) { return substr($w,0,$-[0]).$1.'fe'; }
    if ($w =~ /([m|l])ice$/) { return substr($w,0,$-[0]).$1.'ouse'; }
    if ($w =~ /([ti])a$/) { return substr($w,0,$-[0]).$1.'um'; }
    if ($w =~ /(alias|status)es$/) { return substr($w,0,$-[0]).$1; }
    if ($w =~ /(bus)es$/) { return substr($w,0,$-[0]).$1; }
    if ($w =~ /(cris|ax|test)es$/) { return substr($w,0,$-[0]).$1.'is'; }
    if ($w =~ /(matr)ices$/) { return substr($w,0,$-[0]).$1.'ix'; }
    if ($w =~ /(n)ews$/) { return substr($w,0,$-[0]).$1.'ews'; }
    if ($w =~ /(o)es$/) { return substr($w,0,$-[0]).$1; }
    if ($w =~ /(octop|vir)i$/) { return substr($w,0,$-[0]).$1.'us'; }
    if ($w =~ /(quiz)zes$/) { return substr($w,0,$-[0]).$1; }
    if ($w =~ /(vert|ind)ices$/) { return substr($w,0,$-[0]).$1.'ex'; }
    if ($w =~ /(x|ch|ss|sh)es$/) { return substr($w,0,$-[0]).$1; }
    if ($w =~ /s$/) { return substr($w,0,length($w)-1); }
    if ($w =~ /^(ox)en$/) { return $1; }
    return $w;
}

sub camelize {
    my $w = shift; my $out=''; my $cap=1;
    for my $c (split //, $w) {
        if ($c eq '_') { $cap=1; next; }
        $out .= $cap ? uc($c) : $c; $cap=0;
    }
    return $out;
}

sub underscore {
    my $w = shift; my $out=''; my $i=0;
    for my $c (split //, $w) {
        if ($c =~ /[A-Z]/) { $out .= '_' if $i>0; $out .= lc($c); }
        else { $out .= $c; }
        $i++;
    }
    return $out;
}

sub classify { camelize(singularize($_[0])) }
sub tableize { pluralize(underscore($_[0])) }
sub isPlural { singularize($_[0]) ne $_[0] ? '1':'0' }
sub isSingular { singularize($_[0]) eq $_[0] ? '1':'0' }

my @words;
my @endings = qw(s es ses sses ies ves fes oes xes ches shes zes ice a ia ta i en um us is os ss zzes eis ys ays eys oys asis esis isis aris eris);
my @stems = ('','a','ab','foo','bar','x','qu','the','ban','cat','dog','matr','vert','ind','octop','vir','cris','ax','test','quiz','bus','alias','status','mo','lo','kni','o','ox','The','Foo','B','QU');
