//! Byte-oriented inflection library mirroring the C++ Inflector API.
//! All operations are on raw bytes with C-locale ASCII semantics.

pub struct Inflector;

const UNCOUNTABLES: [&[u8]; 10] = [
    b"equipment",
    b"information",
    b"rice",
    b"money",
    b"species",
    b"series",
    b"fish",
    b"sheep",
    b"jeans",
    b"police",
];

fn to_upper(b: u8) -> u8 {
    if b.is_ascii_lowercase() {
        b - 32
    } else {
        b
    }
}

fn to_lower(b: u8) -> u8 {
    if b.is_ascii_uppercase() {
        b + 32
    } else {
        b
    }
}

/// C-locale isspace: space, \t, \n, \v, \f, \r.
fn is_space(b: u8) -> bool {
    matches!(b, b' ' | b'\t' | b'\n' | 0x0B | 0x0C | b'\r')
}

fn is_uncountable(w: &[u8]) -> bool {
    UNCOUNTABLES.iter().any(|u| *u == w)
}

impl Inflector {
    pub fn pluralize(w: &[u8]) -> Vec<u8> {
        if is_uncountable(w) {
            return w.to_vec();
        }
        let mut r = w.to_vec();
        r.push(b's');
        r
    }

    pub fn singularize(w: &[u8]) -> Vec<u8> {
        if is_uncountable(w) {
            return w.to_vec();
        }
        let n = w.len();

        // Rule 1: Y+"ses" -> Y + ("a" if Y=="analy") + "sis"
        for y in [
            &b"analy"[..],
            b"ba",
            b"diagno",
            b"parenthe",
            b"progno",
            b"synop",
            b"the",
        ] {
            let mut suffix = y.to_vec();
            suffix.extend_from_slice(b"ses");
            if w.ends_with(&suffix) {
                let mut r = w[..n - suffix.len()].to_vec();
                r.extend_from_slice(y);
                if y == b"analy" {
                    r.push(b'a');
                }
                r.extend_from_slice(b"sis");
                return r;
            }
        }

        // Rule 2: ends with "ies"
        if w.ends_with(b"ies") {
            if w.ends_with(b"quies") {
                let mut r = w[..n - 3].to_vec();
                r.push(b'y');
                return r;
            } else if n >= 4 && !matches!(w[n - 4], b'a' | b'e' | b'i' | b'o' | b'u' | b'y') {
                let mut r = w[..n - 3].to_vec();
                r.push(b'y');
                return r;
            }
            // else fall through
        }

        // Rule 3: ends with "ves", len>=4, byte at len-4 != 'f' -> "fe"
        if w.ends_with(b"ves") && n >= 4 && w[n - 4] != b'f' {
            let mut r = w[..n - 3].to_vec();
            r.extend_from_slice(b"fe");
            return r;
        }

        // Rule 4: ends with "ice", len>=4, byte at len-4 in {'m','|','l'} -> "ouse"
        if w.ends_with(b"ice") && n >= 4 && matches!(w[n - 4], b'm' | b'|' | b'l') {
            let mut r = w[..n - 3].to_vec();
            r.extend_from_slice(b"ouse");
            return r;
        }

        // Rule 5: ends with "a", len>=2, byte at len-2 in {'t','i'} -> "um"
        if w.ends_with(b"a") && n >= 2 && matches!(w[n - 2], b't' | b'i') {
            let mut r = w[..n - 1].to_vec();
            r.extend_from_slice(b"um");
            return r;
        }

        // Rule 6: "aliases"/"statuses" -> strip "es"
        for suf in [&b"aliases"[..], b"statuses"] {
            if w.ends_with(suf) {
                return w[..n - 2].to_vec();
            }
        }

        // Rule 7: "buses" -> strip "es"
        if w.ends_with(b"buses") {
            return w[..n - 2].to_vec();
        }

        // Rule 8: crises->crisis, axes->axis, testes->testis (replace "es" with "is")
        for suf in [&b"crises"[..], b"axes", b"testes"] {
            if w.ends_with(suf) {
                let mut r = w[..n - 2].to_vec();
                r.extend_from_slice(b"is");
                return r;
            }
        }

        // Rule 9: "matrices" -> replace "ices" with "ix"
        if w.ends_with(b"matrices") {
            let mut r = w[..n - 4].to_vec();
            r.extend_from_slice(b"ix");
            return r;
        }

        // Rule 10: "news" -> itself (stops processing)
        if w.ends_with(b"news") {
            return w.to_vec();
        }

        // Rule 11: "oes" -> strip "es"
        if w.ends_with(b"oes") {
            return w[..n - 2].to_vec();
        }

        // Rule 12: "octopi" -> "octopus"; "viri" -> "virus" (replace trailing "i" with "us")
        for suf in [&b"octopi"[..], b"viri"] {
            if w.ends_with(suf) {
                let mut r = w[..n - 1].to_vec();
                r.extend_from_slice(b"us");
                return r;
            }
        }

        // Rule 13: "quizzes" -> strip "zes"
        if w.ends_with(b"quizzes") {
            return w[..n - 3].to_vec();
        }

        // Rule 14: "vertices" -> "ex"; "indices" -> "ex" (replace "ices" with "ex")
        for suf in [&b"vertices"[..], b"indices"] {
            if w.ends_with(suf) {
                let mut r = w[..n - 4].to_vec();
                r.extend_from_slice(b"ex");
                return r;
            }
        }

        // Rule 15: xes/ches/sses/shes -> strip "es"
        for suf in [&b"xes"[..], b"ches", b"sses", b"shes"] {
            if w.ends_with(suf) {
                return w[..n - 2].to_vec();
            }
        }

        // Rule 16: ends with "s" -> strip one "s"
        if w.ends_with(b"s") {
            return w[..n - 1].to_vec();
        }

        // Rule 17: exactly "oxen" -> "ox"
        if w == b"oxen" {
            return b"ox".to_vec();
        }

        w.to_vec()
    }

    pub fn camelize(w: &[u8]) -> Vec<u8> {
        let mut r = Vec::with_capacity(w.len());
        for (i, seg) in w.split(|&b| b == b'_').enumerate() {
            if i == 0 {
                r.extend_from_slice(seg);
            } else if !seg.is_empty() {
                r.push(to_upper(seg[0]));
                r.extend_from_slice(&seg[1..]);
            }
        }
        r
    }

    pub fn camelize_upper(w: &[u8]) -> Vec<u8> {
        let mut r = Self::camelize(w);
        if !r.is_empty() {
            r[0] = to_upper(r[0]);
        }
        r
    }

    pub fn underscore(w: &[u8]) -> Vec<u8> {
        let mut r = Vec::with_capacity(w.len() + 4);
        for (i, &b) in w.iter().enumerate() {
            if b.is_ascii_uppercase() {
                if i > 0 {
                    r.push(b'_');
                }
                r.push(to_lower(b));
            } else {
                r.push(b);
            }
        }
        r
    }

    pub fn classify(w: &[u8]) -> Vec<u8> {
        Self::camelize_upper(&Self::singularize(w))
    }

    pub fn tableize(w: &[u8]) -> Vec<u8> {
        Self::pluralize(&Self::underscore(w))
    }

    pub fn humanize(w: &[u8]) -> Vec<u8> {
        let mut r: Vec<u8> = w.iter().map(|&b| if b == b'_' { b' ' } else { b }).collect();
        if !r.is_empty() {
            r[0] = to_upper(r[0]);
        }
        r
    }

    pub fn titleize(w: &[u8]) -> Vec<u8> {
        let mut r: Vec<u8> = w.iter().map(|&b| to_lower(b)).collect();
        for i in 0..r.len() {
            if r[i].is_ascii_lowercase() && (i == 0 || is_space(r[i - 1])) {
                r[i] = to_upper(r[i]);
            }
        }
        r
    }

    pub fn dasherize(w: &[u8]) -> Vec<u8> {
        w.iter().map(|&b| if b == b'_' { b'-' } else { b }).collect()
    }

    pub fn parameterize(w: &[u8]) -> Vec<u8> {
        let mut r = Vec::with_capacity(w.len());
        for &b in w {
            if b.is_ascii_alphanumeric() {
                r.push(to_lower(b));
            } else if b == b' ' {
                r.push(b'-');
            }
            // everything else deleted
        }
        while r.first() == Some(&b'-') {
            r.remove(0);
        }
        while r.last() == Some(&b'-') {
            r.pop();
        }
        r
    }

    pub fn upcase(w: &[u8]) -> Vec<u8> {
        w.iter().map(|&b| to_upper(b)).collect()
    }

    pub fn downcase(w: &[u8]) -> Vec<u8> {
        w.iter().map(|&b| to_lower(b)).collect()
    }

    pub fn capitalize(w: &[u8]) -> Vec<u8> {
        let mut r = Self::downcase(w);
        if !r.is_empty() {
            r[0] = to_upper(r[0]);
        }
        r
    }

    pub fn decapitalize(w: &[u8]) -> Vec<u8> {
        let mut r = w.to_vec();
        if !r.is_empty() {
            r[0] = to_lower(r[0]);
        }
        r
    }

    pub fn truncate(w: &[u8], n: usize) -> Vec<u8> {
        if w.len() > n {
            let keep = n - 3; // n=5 -> first 2 bytes + "..."
            let mut r = w[..keep].to_vec();
            r.extend_from_slice(b"...");
            r
        } else {
            w.to_vec()
        }
    }

    pub fn demodulize(s: &[u8]) -> Vec<u8> {
        let pos = s.iter().rposition(|&b| b == b':').map(|p| p + 2);
        match pos {
            Some(p) if p <= s.len() => s[p..].to_vec(),
            // Mirrors C++ std::out_of_range -> abort (SIGABRT) with no stdout.
            _ => std::process::abort(),
        }
    }

    pub fn is_plural(w: &[u8]) -> bool {
        Self::singularize(w) != w
    }

    pub fn is_singular(w: &[u8]) -> bool {
        Self::singularize(w) == w
    }
}

